input.command:
cd /workspace; mkdir -p .run/tmp/diffs; python3 -I - <<'EOF'
import re,os
cur=None;buf=[]
out={}
for line in open('pr/head.diff',encoding='utf-8',errors='replace'):
    m=re.match(r'^diff --git a/(.*?) b/',line)
    if m:
        if cur: out[cur]=buf
        cur=m.group(1);buf=[line]
    else: buf.append(line)
if cur: out[cur]=buf
for k,v in out.items():
    p='.run/tmp/diffs/'+k.replace('/','__')
    open(p,'w').write(''.join(v))
    print(len(v),k)
EOF

