585	/** True when Bridgebuilder runs on a pull request (D-7.5): `--pr`, a PR event, or a base ref in the environment. */
586	export function isPullRequestContext(pr: number | undefined, env: Record<string, string | undefined>): boolean {
587	  if (pr !== undefined && pr !== null) return true;
588	  const ev = env.GITHUB_EVENT_NAME ?? "";
589	  if (ev === "pull_request" || ev === "pull_request_target") return true;
590	  return (env.GITHUB_BASE_REF ?? "") !== "";
591	}
